-- public.damaged_in_stores(p_world uuid, p_uid uuid)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.damaged_in_stores(p_world uuid, p_uid uuid)
 RETURNS item
 LANGUAGE sql
 STABLE
AS $function$
  select i.* from item i join crate c on c.world_id = i.world_id and c.id = i.crate
  where i.world_id = p_world and i.holder = 'crate' and i.dmg > 1 and not unrestored(i.def) and not unmendable(i.def)
    and on_home_deed(p_world, p_uid, c.x, c.y)
  order by i.dmg desc limit 1
$function$
